import 'package:flutter/material.dart';
import 'package:priceshield/core/services/priceshield_api_client.dart';
class ComplaintDetailsScreen extends StatefulWidget { const ComplaintDetailsScreen({super.key, required this.complaintId}); final String complaintId; @override State<ComplaintDetailsScreen> createState() => _ComplaintDetailsScreenState(); }
class _ComplaintDetailsScreenState extends State<ComplaintDetailsScreen> {
  late Future<Map<String, dynamic>> _complaint = priceShieldApi.getComplaint(widget.complaintId);
  Future<void> _withdraw() async { try { await priceShieldApi.withdrawComplaint(widget.complaintId); if (mounted) Navigator.pop(context); } on PriceShieldApiException catch (error) { if (mounted) ScaffoldMessenger.of(context).showSnackBar(SnackBar(content: Text(error.message))); } }
  @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Complaint Details')), body: FutureBuilder<Map<String, dynamic>>(future: _complaint, builder: (context, snapshot) { if (snapshot.connectionState != ConnectionState.done) return const Center(child: CircularProgressIndicator()); if (snapshot.hasError) return Center(child: Text('Could not load complaint.')); final data = snapshot.data!; final evidence = data['evidence'] is List ? data['evidence'] as List : const []; return ListView(padding: const EdgeInsets.all(20), children: [Text(data['productName']?.toString() ?? '', style: Theme.of(context).textTheme.headlineSmall), const SizedBox(height: 12), Text('Barcode: ${data['barcode'] ?? ''}'), Text('MRP: ₹${data['mrp'] ?? 0}'), Text('Charged: ₹${data['chargedPrice'] ?? 0}'), Text('Overcharge: ₹${data['overcharge'] ?? 0}'), Text('Status: ${data['status'] ?? ''}'), Text('Address: ${data['address'] ?? ''}'), if (data['description'] != null) Text('Details: ${data['description']}'), const SizedBox(height: 16), ...evidence.whereType<Map>().map((item) => ListTile(leading: const Icon(Icons.attachment), title: Text(item['url']?.toString() ?? 'Evidence'))), if (data['status'] != 'WITHDRAWN') OutlinedButton(onPressed: _withdraw, child: const Text('Withdraw complaint'))]); }));
}
